-- STAGING ONLY. Installed only through the authenticated, fingerprinted setup.
CREATE TABLE IF NOT EXISTS access_email_settings (id INTEGER PRIMARY KEY CHECK(id=1),schema_hash TEXT NOT NULL,key_hash TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 0 CHECK(enabled IN (0,1)),qa_verified_at INTEGER,qa_login_at INTEGER,qa_account_id TEXT,qa_identity_revision INTEGER);
CREATE TABLE IF NOT EXISTS access_email_identities (account_id TEXT PRIMARY KEY REFERENCES audience_accounts(id) ON DELETE CASCADE,email_hash TEXT NOT NULL UNIQUE,sealed_email TEXT NOT NULL,revision INTEGER NOT NULL CHECK(revision>0),verified_at INTEGER NOT NULL,consent_scope TEXT NOT NULL DEFAULT 'account_email_access_v1',consent_at INTEGER NOT NULL,key_hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS access_email_outbox (id TEXT PRIMARY KEY,request_id TEXT NOT NULL,actor_hash TEXT NOT NULL,purpose TEXT NOT NULL CHECK(purpose IN ('access','verify')),account_id TEXT NOT NULL,email_hash TEXT NOT NULL,identity_revision INTEGER NOT NULL,actor_credential TEXT,actor_device INTEGER NOT NULL DEFAULT 0,token_hash TEXT NOT NULL UNIQUE,sealed_payload TEXT,sealed_address TEXT,state TEXT NOT NULL CHECK(state IN ('queued','sending','accepted','redeemed','expired','cancelled','failed')),created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,attempts INTEGER NOT NULL DEFAULT 0 CHECK(attempts BETWEEN 0 AND 3),lease_owner TEXT,lease_until INTEGER NOT NULL DEFAULT 0,provider_id TEXT,redeemed_hash TEXT,redeemed_account TEXT,redeemed_revision INTEGER,UNIQUE(actor_hash,request_id),CHECK(expires_at>created_at),CHECK(state NOT IN ('queued','sending') OR sealed_payload IS NOT NULL));
CREATE UNIQUE INDEX IF NOT EXISTS access_email_active ON access_email_outbox(email_hash,purpose) WHERE state IN ('queued','sending','accepted');
CREATE INDEX IF NOT EXISTS access_email_ready ON access_email_outbox(state,expires_at,lease_until);
CREATE TABLE IF NOT EXISTS access_email_rates (bucket TEXT PRIMARY KEY,hits INTEGER NOT NULL,resets_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS access_email_checks (id TEXT PRIMARY KEY,valid INTEGER NOT NULL CHECK(valid=1));
